record Expiring<T>(T payload, long deadlineNanos) implements Delayed {
    public long getDelay(TimeUnit unit) { return unit.convert(deadlineNanos - System.nanoTime(), NANOSECONDS); }
    public int compareTo(Delayed o) { return Long.compare(getDelay(NANOSECONDS), o.getDelay(NANOSECONDS)); }
}

DelayQueue<Expiring<Msg>> queue = new DelayQueue<>();
Expiring<Msg> stale = queue.take();     // blocks until the head has expired
deadLetter(stale.payload());            // expired: never processed

